from agent import *from models.products import *def process_frontpage(data: Response, context: dict[str, str], session: Session):    for prod in data.xpath("//a[@rel='bookmark']"):        url = prod.xpath("@href").string()        title = prod.xpath("text()").string(multiple=True)        if url and title:            session.queue(Request(url), process_review, dict(context, url=url, title=title))    next_page = data.xpath("//a[@class='next page-numbers']/@href").string()    if next_page:        session.queue(Request(next_page), process_frontpage, {})def process_review(data: Response, context: dict[str, str], session: Session):    product = Product()    product.name = context['title'].replace('im Test', '')    product.url = context['url']    product.ssid = context['url'].split('/')[-2]    product.category = data.xpath("(//a[@itemprop='item'])[last()]//text()").string()    review = Review()    review.type = 'pro'    review.title = context['title']    review.url = context['url']    review.ssid = product.ssid    date = data.xpath("//span[@class='atkp-disclaimer']/text()").string()    if date:        review.date = ''.join(date.split('Zuletzt aktualisiert am')[-1].split('.', 2)[:-1]).split('um')[0]    rating = data.xpath("//table[@class='bewertung_table']/tr[contains(., 'Gesamt')]/td[2]//text()").string()    if rating:        review.grades.append(Grade(type='overall', name='Bewertung', value=float(rating.replace('%', '')), best=100))    grades = data.xpath("//table[@class='bewertung_table']/tr[contains(., 'Gesamt')]/following-sibling::tr")    for grade in grades:        grade_name = grade.xpath("td[1]//text()").string()        grade_value = grade.xpath("td[2]//text()").string()        if grade_name and grade_value:            review.grades.append(Grade(name=grade_name, value=float(grade_value.replace('%', '')), best=100))        for pro in data.xpath("//li[.//i[@class='fa fa-plus-circle pro']]//text()"):        if pro:            review.add_property(type='pros', value=pro.string())    for con in data.xpath("//li[.//i[@class='fa fa-minus-circle contra']]//text()"):        if con:            review.add_property(type='cons', value=con.string())        summary = data.xpath("//div[contains(@class, 'entry-content')]//p[.//strong]").first()    if summary:        review.properties.append(ReviewProperty(type='summary', value=summary.xpath(".//text()").string(multiple=True)))        conclusion = data.xpath("//h2[contains(., 'Fazit')]/following-sibling::p//text()").string(multiple=True)    if conclusion:        review.properties.append(ReviewProperty(type='conclusion', value=conclusion))    excerpt = data.xpath("//div[contains(@class,'entry-content')]//p//text()").string(multiple=True)    if excerpt:        if summary:            excerpt = excerpt.replace(summary.xpath(".//text()").string(multiple=True), '')        if conclusion:            excerpt = excerpt.replace(conclusion, '')        review.add_property(type='excerpt', value=excerpt)    product.reviews.append(review)    session.emit(product)def run(context: dict[str, str], session: Session):   session.queue(Request('https://www.testfazit.de/?s=im+test'), process_frontpage, {})